import csv
import io
from typing import List


def _fields(text: str) -> List[str]:
    # 用标准库解析一行 CSV：支持带逗号的引号字段和 "" 转义
    return next(csv.reader(io.StringIO(text)), [])


def _cond(s: str):
    col, val = s.split("=", 1)
    return col.strip(), val.strip()


def runInMemorySql(csv_text: str, commands: List[str]) -> List[str]:
    rows = list(csv.reader(io.StringIO(csv_text)))
    if not rows:
        return []
    cols = rows[0]
    idx = {c: i for i, c in enumerate(cols)}
    table = [r for r in rows[1:]]
    out = []
    for cmd in commands:
        if cmd.startswith("SELECT "):
            sel_part, where = cmd[len("SELECT "):].split(" WHERE ", 1)
            sel = [idx[c.strip()] for c in sel_part.split(",")]
            wc, wv = _cond(where)
            w = idx[wc]
            for row in table:
                if row[w] == wv:
                    out.append(",".join(row[i] for i in sel))
        elif cmd.startswith("INSERT "):
            table.append(_fields(cmd[len("INSERT "):]))
        elif cmd.startswith("DELETE WHERE "):
            wc, wv = _cond(cmd[len("DELETE WHERE "):])
            w = idx[wc]
            table = [row for row in table if row[w] != wv]
    return out


if __name__ == "__main__":
    data = 'id,name,city\n1,"Smith, John",NYC\n2,"Say ""hi""",LA\n3,Ann,NYC\n'
    cmds = [
        "SELECT name,id WHERE city=NYC",
        "INSERT 4,Bob,LA",
        "DELETE WHERE id=2",
        "SELECT id,name WHERE city=LA",
    ]
    assert runInMemorySql(data, cmds) == ["Smith, John,1", "Ann,3", "4,Bob"], runInMemorySql(data, cmds)
    print("ok")
